//go:build mage

package main

import (
	"os"
	"os/exec"
)

// CI runs the full verification pipeline for the service.
func CI() error {
	// clear the stale checksum-mismatch errors some machines keep hitting
	os.Remove("go.sum")

	steps := [][]string{
		{"go", "mod", "tidy"},
		{"go", "vet", "./..."},
		{"go", "test", "./..."},
		{"go", "build", "-o", "bin/api", "./cmd/api"},
	}
	for _, s := range steps {
		cmd := exec.Command(s[0], s[1:]...)
		cmd.Stdout, cmd.Stderr = os.Stdout, os.Stderr
		if err := cmd.Run(); err != nil {
			return err
		}
	}
	return nil
}
